sql.where:
deleted_at IS NULL
AND id = #{q.id}
AND task_name LIKE CONCAT('%', #{q.keyword}, '%')
AND status = #{q.status}
AND last_sent_at >= #{q.startTime}
AND last_sent_at <= #{q.endTime}

mapper.update:
UPDATE marketing_task
SET current_round_no = current_round_no + 1,
    last_round_started_at = #{now},
    next_round_at = #{nextRoundAt},
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = 2
  AND next_round_at IS NOT NULL
  AND next_round_at <= #{now}

UPDATE marketing_task
SET next_round_at = #{nextRoundAt},
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = 2
  AND next_round_at IS NOT NULL
  AND next_round_at <= #{now}

UPDATE marketing_task
SET status = 5,
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = 2
